\begin{equation}\label{K'}
K'=K-\frac{1}{n}\phi(t)g,
\end{equation}
where  $\phi:\R\to\R$ will be chosen momentarily.

theorem.raw:
\label{MOTS}
Let $(M^{n+1},g,K)$ be an initial data set for a space-time, and let $\partial\Omega_{\out}=\Sigma_{\out}$ denote the  outermost MOTS in $M$. Let $\Omega$ be a smooth domain in $M$ with $\Omega_\out\subset\Omega$, and whose boundary, $\partial\Omega$, is a mean convex closed and bounded outer trapped embedded hypersurface in $M$. Then for $2\le n\le 6$ the following hold: 
\begin{enumerate}[(i)]
\item Let  $\lambda=\max_i\{|\l_i|, \l_i\text{  eigenvalue of  } K\}$. Then, for any $0<\e\le \min\left\{\frac{1}{(n+1)\lambda}, \frac12\right\}$  there exists a  solution $\hat{u}_{\varepsilon}\in C^\infty(\Omega\setminus\Omega_\out)$ of the equation $(*_{\hat{\varepsilon}})$ that is zero on $\partial\Omega$ and blows up to infinity over $\Sigma_\out$,  that is $\lim_{x\to x_0}\hat u_\e(x)=\infty$ for any $x_0\in \Sigma_\out$.
\item There exists a sequence of $\hat{u}_{\varepsilon_k}$ as in (i) with $\e_k\downarrow 0$ such that $u_{\e_k}\to u$ in $C^0(\Omega_1\cup\partial \Omega)$, where $u\in C^{0,1}(\Omega_1\cup\partial\Omega)$  and $\Omega_1\subset \Omega\setminus \Omega_\out$ is such that $\partial\Omega\subset\partial\Omega_1$ and $\partial^* (\Omega\setminus\Omega_1)$ is a {\it generalized} MOTS (see Definition~\ref{weakMOTS} and Remark~\ref{weakrmk}).
\end{enumerate}

\label{blowup}
There exists an $\e_0$ depending only on the initial data, such that for any $\e\le \e_0$ the following holds. There exists a solution $\hat u_\e\in C^\infty(\Omega_0)$ of the equation ($*_{\hat\e}$), where  $\Omega_0=\Omega\setminus\ov\Omega_\infty$, such that $\hat u_\e$ blows up over the inner boundary $\partial\Omega_0\setminus\partial\Omega=\Sigma_\out$ (the outermost MOTS) and is  zero over the outer boundary $\partial \Omega$.

 Consequently the function $u_\e=\e\hat u_\e$ is then a smooth solution of ($*_{\e}$) in $\Omega_0$ that blows up over the inner boundary $\Sigma_\out$ (the outermost MOTS) and is  zero over the outer boundary $\partial \Omega$.

lemma.raw:
\label{supest}
 Let  $\lambda=\max_i\{|\l_i|, \l_i\text{  eigenvalue of  } K\}$. For any $\e\le \frac{1}{(n+1)\lambda}$ solutions $\hat{u}$ of $(*_{\hat{\varepsilon},\kappa,s})$ satisfy the  estimate
\begin{equation*}\label{supbnd}
0\leq \hat{u}\leq \frac{2}{\varepsilon\kappa}.
\end{equation*}

\label{interiorforkappa}

 For any $\e\le \frac12$ solutions $\hat{u}$ of  $(*_{\hat{\varepsilon},\kappa,s})$  satisfy the estimate
\begin{equation*}
\sup_{\Omega}|\nabla \hat{u}|\leq \exp(\eta\sup_{\Omega} \hat{u})\cdot\sup_{\partial\Omega}\left(\frac{1}{\varepsilon}+\sqrt{1+|\nabla \hat{u}|^2}\right),
\end{equation*}
where $\eta$ is a constant that depends only on the initial data, in fact $\eta=\eta(n,\Ric,\|K\|_{C^1})$.

\label{boundaryforkappa}
Assume that  $\partial\Omega$ is smooth,  strictly mean convex and outer untrapped with respect to the outward pointing unit normal. 

Then, 

solutions $\hat{u}$ of $(*_{\hat{\varepsilon},\kappa,s})$ satisfy the estimate
\begin{equation*}
\sup_{\partial\Omega}|\nabla \hat{u}|\leq C(\|K\|_{C_0},\varepsilon,\theta^+_{\partial\Omega}),\end{equation*}
where we recall that $\theta^+_{\partial\Omega}$ is the null mean curvature of ${\partial\Omega}$ with respect to its future directed outward pointing null vector field.

\label{unigradest} Let $\e\le \frac12$ and $u_\e\in C^\infty(\Omega_0)$ be a solution  of $(*_{\varepsilon})$  as  in  Theorem~\ref{blowup}. Then, $u_\e$  satisfies the estimate
\begin{equation*}
\sup_{\Omega_{T/2}}|\nabla u_{\varepsilon}|\leq \frac{2}{\eta T}\exp(\eta T)\cdot\sup_{\partial\Omega}(1+\sqrt{\varepsilon^2+|\nabla u_{\varepsilon}^2|}),
\end{equation*}
where $\eta$ is a constant that depends only on the initial data, in fact $\eta=\eta(n,\Ric,\|K\|_{C^1})$, and $\Omega_T=\{x\in\bar{\Omega}_0:u_{\varepsilon}(x)\leq T\}$.

\label{bdrygradest}
There exist constants $C$ and $\e_0$,  depending only on the initial data,  such that for any $\e\le\e_0$ and any solution $u_\e\in C^\infty(\Omega_0)$ of $(*_{\varepsilon})$, as  in  Theorem~\ref{blowup}, the following estimate holds
\[\sup_{\partial\Omega}|\nabla u_{\varepsilon}|\le C.\]

\label{normalintest}
Let $u_{{\varepsilon}}\in C^\infty(\Omega_0)$ be a solution of $(*_{{\varepsilon}})$ as  in  Theorem~\ref{blowup}. Then
\begin{equation}\label{intest}
\int_{\Omega_0}\frac{1}{\sqrt{\e^2+|\nabla{u}_{\varepsilon}|^2}}dx\leq|\partial\Omega_0|+(n+2)\lambda|\Omega|,
\end{equation}
where $\lambda=\max_i\{|\l_i|, \l_i\text{  eigenvalue of  } K\}$.

\label{mainconvII}
 Assume that $\mu_{t_i}=\H^n\res\Sigma_{t_i}\to\mu_\infty$ as Radon measures and $E_{t_i}\to E_\infty$ as finite perimeter sets (where we use the notation of Definition~\ref{U}). Then 
 \begin{equation}\label{muinfty}
\mu_\infty\res\partial^*E_\infty=\H^{n}\res \partial^* E_\infty.
\end{equation}

proof.raw:
Since $\hat u|_{\partial\Omega}=0$, either $\hat{u}\leq0$ or $\hat{u}$ has an interior maximum. At an interior maximum point we have 
\begin{align*}
\max_{\Omega}\kappa \hat{u}= g^{ij}\hat{u}_{ij}-sg^{ij}K_{ij}+\frac{s}{\varepsilon}\leq (n+1)\lambda+\frac{1}{\varepsilon}.
\end{align*}
Since, for $\varepsilon\leq\frac{1}{(n+1)\lambda}$, zero is a subsolution of $(*_{\hat{\varepsilon},\kappa,s})$  we find
\begin{equation*}
0\leq \hat{u}\leq \frac{(n+1)\lambda}{\kappa}+\frac{1}{\varepsilon\kappa}\le \frac{2}{\varepsilon\kappa}.
\end{equation*}

For the gradient function $v(x,f(x)):=\sqrt{1+|\nabla f(x)|^2}$ of a hypersurface  $N=\graph f$ we have
\begin{equation}\label{jacobi}
\Delta^N v=\frac{2}{v}|\nabla^N v|^2-v^2\bar g(\nabla^N H,\tau)+v|A|^2+v\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma),
\end{equation}
where $\tau=\frac{\partial}{\partial z}$ is the unit vector pointing in the upward, $\mathbb{R}$, direction of $M\times\mathbb{R}$, $\nu$ is the upward pointing unit normal to $N=\graph f$, $H$ and $A$ are the mean curvature and the second fundamental form of $N$,  $\gamma:=\frac{\text{pr}_{TM}\nu}{|\text{pr}_{TM}\nu|}$ in case $\nu\ne \tau$ and zero otherwise,  and $\Ric=\Ric_M$ is the Ricci curvature of $M$. For details of the derivation of \eqref{jacobi} see \cite[(13)]{S08}. Recall also that $\bar g$ is the metric in the product manifold $M\times\R$ as defined in \eqref{product}.  We follow the general approach in \cite[Lemma 3.2]{S08} to show that we can obtain a gradient bound given an a-priori height bound and compute $\Delta^N(wv)$, where
 $w(x,z):=\exp(-\eta z)$, for $(x,z)\in M\times\R$ and $\eta>0$ a constant to be chosen later. For the function $w$ we have
\[\nabla^N w=-\eta w\left(\tau-\frac1v\nu\right)\,\text{ and }\,\Delta^N w=\eta^2\left(1-\frac{1}{v^2}\right)w+\eta\frac{H}{v}w,\]
and combining these with \eqref{jacobi}, we obtain
\begin{equation}\label{jacobi2}
\begin{split}
\Delta^N(wv)=\frac{2}{v}\bar g(\nabla v,\nabla (wv))+wv\Biggl(&|A|^2+\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)\\
&+\eta^2\left(1-\frac{1}{v^2}\right)+\eta\frac{H}{v}-v\bar g(\nabla^N H,\tau)\Biggr).
\end{split}
\end{equation}
In order to obtain a contradiction, define $C_1:=\sup_{\partial\Omega}\varepsilon\sqrt{1+|\nabla \hat{u}|^2}$ and assume 
\begin{equation}\label{contradiction1}
\sup_{\Omega}(\exp(-\eta \hat{u})\varepsilon\sqrt{1+|\nabla \hat{u}|^2})>\max\{C_1,1\},
\end{equation}
which must be attained at an interior point $x_0$. Letting $N=\graph\hat{u}$, equation $(*_{\hat{\varepsilon},\kappa, s})$ implies that 
\begin{equation}\label{floweqn}
H+sP=\dfrac{s}{\varepsilon v}-\kappa\hat{u},
\end{equation}
where $H+P$ is the null mean curvature of $N$. 
Now, using the expression for $\nabla^N w$,  we find 
\begin{align*}
wv^2\bar g(\nabla^N H,\tau)=&-\frac{s}{\varepsilon}\bar g(\nabla^N (wv),\tau)+\frac{sv}{\varepsilon}\bar g(\nabla^N w,\tau)-wv^2s\bar g(\nabla^N P,\tau)\\
&-wv^2\kappa \bar g(\nabla^N \hat u,\tau)\\
=&-\frac{s}{\varepsilon}\bar g(\nabla^N (wv),\tau)-\frac{s}{\varepsilon}\eta wv\left(1-\tfrac{1}{v^2}\right)-wv^2s\bar g(\nabla^N P,\tau)\\
&-wv^2\kappa \bar g(\nabla^N  \hat u,\tau).
\end{align*}
Note that $\nabla^NP=\ov\nabla P-\bar g(\ov\nabla P,\nu)\nu$ (where $\ov\nabla=\nabla^{M\times\R}$),  $K$ (as well as $\nu$)  is extended trivially in the $\tau$ direction so that $\bar g(\ov\nabla P,\tau)=0$, and $\bar g(\tau,\nu)=\frac{1}{v}$. Using these, we obtain
\begin{equation}\label{MNest}
\begin{split}
vs\bar g(\nabla^N P,\tau)=-s\bar g(\ov\nabla P,\nu)&\geq-c(1+|A|),\\
v\kappa \bar g(\nabla^N  \hat{u},\tau)=-\kappa \bar g(\ov\nabla \hat{u},\nu)&=\frac{\kappa|\nabla \hat{u}|^2}{v}\geq0,
\end{split}
\end{equation}
where $c=c(n, \|K\|_{C^1})\ge1$, so that, using the Cauchy--Schwarz inequality, we have
\begin{equation}\label{nablaHest}
\begin{split}
wv^2\bar g(\nabla^N H,\tau)\leq-\frac{s}{\varepsilon}\bar g(\nabla^N (wv),\tau)&-\frac{s}{\varepsilon}\eta wv\left(1-\frac{1}{v^2}\right)+2c^2wv+ wv\frac{|A|^2}{2}.
\end{split}
\end{equation}
At a maximum point $x_0$, where $\Delta^N(wv)\leq0$ and $\nabla^N(wv)=0$, (\ref{jacobi2}) becomes
\begin{align*}
0\geq&|A|^2 +\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)+\eta^2\left(1-\frac{1}{v^2}\right)+\eta\frac{H}{v}-v\bar g(\nabla^N H,\tau),
\end{align*}
where the constant $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}. Using (\ref{floweqn}),  \eqref{nablaHest} and Lemma \ref{supest}, we obtain
\[
\begin{split}
0\geq \frac{|A|^2}{2}&+\left(1-\frac{1}{v^2}\right)\left(\Ric(\gamma,\gamma)
+\frac{s\eta}{\varepsilon}+\eta^2\right)\\
&+\frac{s\eta}{\varepsilon v^2}-\eta\frac{\|K\|_{C^0}}{v}-\frac{2\eta}{\e v}-2c^2.
\end{split}
\]
By the assumption (\ref{contradiction1}), we find that $v(x_0)>\frac{1}{\varepsilon}$ and thus $(1-\frac{1}{v^2})>\frac{1}{2}$ when $\varepsilon\leq\frac{1}{2}$. Then, the above becomes
\begin{equation*}
0\geq \frac{\eta^2}{2}+\frac{1}{2}\Ric(\gamma,\gamma)-2c^2-\eta\left(\frac12\|K\|_{C^0}+2\right),
\end{equation*}
where the constant $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}, and setting $\eta=\eta(n,\Ric,\|K\|_{C^1})$ large enough so that the right-hand side is strictly positive leads to a contradiction and thus  hypothesis (\ref{contradiction1}) is false.

The proof follows that of \cite[Lemma 3]{SY81}.
The idea is to apply the method of continuity to the equation $(*_{\hat{\varepsilon},\kappa,s})$. To this end, fix $\varepsilon\le \min\left\{\frac{1}{(n+1)\lambda},\frac12\right\}$ and $\k>0$,  and define
\begin{align*}
F^s(w):=\dvg\left(\frac{\nabla w}{\sqrt{|\nabla w|^2+1}}\right)&-s\left(g^{ij}-\dfrac{\nabla^iw\nabla^jw}{|\nabla w|^2+1}\right)K_{ij}\\
&+\dfrac{s}{\varepsilon \sqrt{|\nabla w|^2+1}}-\kappa w.
\end{align*}
For any $\a\in (0,1)$,  the map 
\begin{equation*}
F: C^{2,\alpha}_0(\bar{\Omega})\times[0,1]\to C^{\alpha}(\bar{\Omega}) 
\end{equation*}
given by $F(w,s):=F^s(w)$  has the solution $F(0,0)=0$. Let $I$ be the set of $s$ such that $(*_{\varepsilon,\kappa,s})$ has a solution in $C^{2,\alpha}(\bar{\Omega})$ or equivalently the set of $s$ for which there exists $w\in C^{2,\alpha}_0(\bar{\Omega})$ such that $F(w,s)=0$. Then $0\in I$ and we will show that $I$ is an open and closed subset of $[0,1]$, which implies that $I=[0,1]$, thus proving the lemma. To show that $I$ is closed one uses  the a-priori estimates in Lemmas \ref{supest}, \ref{interiorforkappa} and \ref{kappaexists}, standard PDE estimates (which imply `higher' a-priori estimates for a solution; in particular $C^{2,\a}$ for any $\a\in (0,1)$) and the Arzela-Ascoli theorem. To show that $I$ is open, one has to linearize $F^s$ at a solution $f_0$ and apply the inverse function theorem for Banach spaces. For the details of these two claims we refer the reader to \cite[Lemmas 2 and 3]{SY81}   where the arguments on the fact that $I$ is both open and closed are carried out in detail. We remark that the only difference between our case and \cite[Lemma 3]{SY81} is that one has to add the factor $-\frac{\nabla^i f_0}{\e(|\nabla f_0|^2+1)^\frac32}$
in the term $B^i$ that appears in the linearization of $F^s$ at a solution $f_0$ (the notation being here as in \cite[Lemma 3]{SY81}).

We take a similar approach to that of the proof of Lemma~\ref{interiorforkappa}. Let $N=\graph \hat u_\e$ and $v=\sqrt{1+|\nabla \hat u_\e|^2}$, where recall that $\hat u_\e=\e u_\e$ is a solution of $(*_{\hat{\varepsilon}})$. Let also $w(x,z):=\exp(-\varepsilon\eta z)$ for $(x,z)\in M\times\R$ and $w_0=\exp(-\eta T)$, so that $w-w_0=0$ when $z=\e^{-1}T$. We compute $\Delta^N((w-w_0)v)$ on $N$, similarly to \eqref{jacobi2} in the proof of Lemma  \ref{interiorforkappa}, as follows. We first note that
\[
\nabla^N w=-\e\eta w\left(\tau-\frac1v\nu\right)\,,\,\,\,\Delta^N w=\e^2\eta^2\left(1-\frac{1}{v^2}\right)w+\e\eta\frac{H}{v}w,
\]
where the notation here and throughout this proof is as in the proof of Lemma  \ref{interiorforkappa}. Thus (using \eqref{jacobi} from the proof of Lemma  \ref{interiorforkappa}) we obtain
\begin{equation}\label{newJacobiEqn}
\begin{split}
\Delta^N((w-w_0)v)=&\frac{2}{v}\bar g(\nabla^Nv,\nabla^N((w-w_0)v))
\\
&+(w-w_0)v\Bigg(|A|^2+\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)\\
&+(\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}-v\bar g(\nabla^NH,\tau)\Bigg)\\
&+w_0v\left((\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}\right).
\end{split}
\end{equation}
To argue by contradiction, define $C_1:=\sup_{\partial\Omega}\varepsilon\sqrt{1+|\nabla \hat{u}_\e|^2}$ and assume 
\begin{equation}\label{contradiction}
\sup_{\Omega_T}((\exp(-\eta \varepsilon\hat{u})-\exp(-\eta T))\varepsilon\sqrt{1+|\nabla \hat{u}_\e|^2})>\max\{C_1,1\},
\end{equation}
which must be attained at an interior point $x_0$. Since $N=\graph\hat{u}_\e$, equation $(*_{\hat{\varepsilon}})$ implies that 
\begin{equation}\label{floweqn2}
H+P=\dfrac{1}{\varepsilon v},
\end{equation}
where $H+P$ is the null mean curvature of $N$.
Proceeding as in Lemma~\ref{interiorforkappa}, analogous to (\ref{nablaHest}) (using also \eqref{MNest} and the expression for $|\nabla^Nw|$), we obtain the following estimate
\begin{align*}
(w-w_0)v^2\bar g(\nabla^NH,\tau)=&-\frac{1}{\varepsilon}\bar g(\nabla^N((w-w_0)v),\tau)\\
&-{\eta} wv\left(1-\frac{1}{v^2}\right)-(w-w_0)v^2g(\nabla^NP,\tau)\\
\leq&-\frac{1}{\varepsilon}\bar g(\nabla^N((w-w_0)v),\tau)\\
&-(w-w_0)v\left({\eta}\left(1-\frac{1}{v^2}\right)-2c^2-\frac{|A|^2}{2}\right)\\
&-w_0v{\eta}\left(1-\frac{1}{v^2}\right),
\end{align*}
where $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}.
At a maximum point $x_0$, where $\Delta((w-w_0)v)\leq0$ and $\nabla((w-w_0)v)=0$, \eqref{newJacobiEqn} reduces to
\begin{align*}
0\geq (w-w_0)v\Bigg(&|A|^2+\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)\\
&+(\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}-v\bar g(\nabla^NH,\tau)\Bigg)\\
&+w_0v\left((\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}\right).
\end{align*}
After implementing the above estimates and also using \eqref{floweqn2}, this becomes
\begin{align*}
0\geq(w-w_0)v\Bigg(\frac{|A|^2}{2}&+\left(1-\frac{1}{v^2}\right)\Bigl(\Ric(\gamma,\gamma)+\eta+(\varepsilon\eta)^2\Bigr)\\
&\hspace{3cm}+\frac{\eta}{v^2}-\varepsilon\eta\frac{\|K\|_{C^0}}{v}-2c^2\Bigg)\\
&+w_0v\left((\eta+(\varepsilon\eta)^2)\left(1-\frac{1}{v^2}\right)+\frac{\eta}{v^2}-\varepsilon\eta\frac{\|K\|_{C^0}}{v}\right).
\end{align*}
By the contradiction hypothesis (\ref{contradiction}), we find that $v(x_0)>\frac{1}{\varepsilon}$ and thus $(1-\frac{1}{v^2})>\frac{1}{2}$, provided that $\varepsilon\leq\frac{1}{2}$. Therefore, after discarding some  positive terms from the right-hand side, we obtain
\begin{equation*}
\begin{split}
0&\geq (w-w_0)v\Bigg(\left(1-\frac{1}{v^2}\right)\left({\eta}+\Ric(\gamma,\gamma)-4c^2\right)+\varepsilon^2\eta\left(\frac{\eta}{2}-\|K\|_{C^0}\right)\Bigg)\\
&\quad+w_0\varepsilon^2\eta\left(\frac{\eta}{2}-\|K\|_{C^0}\right),
\end{split}
\end{equation*}
where the constant $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}. For $\eta=\eta(n,\Ric,\|K\|_{C^1})$ large enough the right-hand side of the above expression becomes  strictly positive, leading to a contradiction. In other words, \eqref{contradiction} cannot be true and therefore we have
\[\sup_{\Omega_T}((\exp(-\eta \varepsilon\hat{u}_\e)-\exp(-\eta T))\varepsilon\sqrt{1+|\nabla \hat{u}_\e|^2})\le\max\{C_1,1\}.\]
For $u_\e=\e\hat u_\e$ we then have
\[\begin{split}\sup_{\Omega_T}((\exp(-\eta{u}_\e)-\exp(-\eta T))\sqrt{\e^2+|\nabla {u}_\e|^2})&\le\max\{C_1,1\}\\
&\le \sup_{\partial\Omega}(1+\sqrt{\e^2+|\nabla {u}_\e|^2}).
\end{split}\]
Restricting now to the region $\Omega_{T/2}$, where 
\[\exp(-\eta{u}_\e)-\exp(-\eta T)\ge \exp(-\eta T/2)-\exp(-\eta T)\ge \frac{\eta T}{2}\exp(-\eta T),\]
we obtain  the required estimate.

remark.raw:
\label{weakrmk}
 If $\partial^* E$ is a generalized MOTS, then by Allard's regularity theorem \cite{Al} (see also \cite{Alex}) we infer that, away from a set of $\H^n$-measure zero, $\partial^*E$ is a $C^{1,\a}$ hypersurface for any $\a\in (0,1)$. This implies that locally (away from a set of $\H^n$-measure zero) it is the graph of a function that satisfies  equation \eqref{Jang} weakly, and using standard PDE methods we obtain that  $\partial^* E$ is smooth, and thus a MOTS in the classical sense, away from a set of $\H^n$-measure zero.

 Furthermore, since the mean curvature is bounded on the reduced boundary, we also have that if  $\partial^* E$ is a generalized MOTS then $\H^n(\partial E\setminus\partial^*E)=0$.

\label{SUrmk} Let $\Sigma^-$ be as above,  satisfying \eqref{P-}. We then have short time existence of a (smooth) solution of the equation
\begin{equation}\label{eqnP-}
\left\lbrace
\begin{aligned}
 \frac{\partial F^-}{\partial t}(x,t) & = -(H+P)(x,t)\nu(x,t), \quad x\in\Sigma^-,\,t\geq0, \\
                         F^-(\Sigma^-,0) & = \Sigma^-,
\end{aligned}
\right.
\end{equation}
where $H+P$ is defined using the new data $K'$ as in  \eqref{K'} and satisfying also \eqref{lK} (see for example \cite{CB, GP99}). That is, there exists $T>0$ and a smooth solution  $F^-:\Sigma^-\times[0,T)\to M$
of  \eqref{eqnP-}. The evolution equation of $H+ P$ (given  in \eqref{heH+P}) along
with  the maximum principle and \eqref{P-}, implies that $\Sigma^-$ flows towards $\Sigma_\out$ and
 $F^-(\Sigma^-, {t_1})\cap F^-(\Sigma^-, {t_2})=\emptyset$ for any $t_1\ne t_2$. For $\tau=\min\{T/2,\s\}$, we let 
 \[ U_\t:=\bigcup_{0<t<\tau}F^-(\Sigma^-, {t})\subset M\]
and let $u^-:U_\t\to \R$ be defined by $u^-(p)=t\Leftrightarrow p\in F^-(\Sigma^-, {t})$. Then, we have that $u^-$ is a smooth solution of the following equation over $\ov U_\t$ 
\begin{equation}\label{ellH+Ps}
\dvg\left( \frac{\nabla u^-}{|\nabla u^-|}\right) +\left(g^{ij}-\dfrac{\nabla^iu^-\nabla^ju^-}{|\nabla u^-|^2}\right)K'_{ij}= \frac{-1}{|\nabla u^-|}
\end{equation}
(cf. $(**)$ and note the change of sign in front of the $K'$-term on the left-hand side), such that $u^-=0$ on $\Sigma^-$ and $u^-=\tau$ on $\partial U_\t\setminus\Sigma^-=F^-(\Sigma^-, \tau)$. Furthermore, there exists some constant $C_0\ge1$ such that
\begin{equation}\label{Dus}
\frac{1}{C_0}\le |\nabla u^-|\le C_0\,\,,\,\,|\nabla^2 u^-|\le C_0\text{    in   }\ov U_\t.
\end{equation}

