\label{main}
\begin{Remark}\label{thmrmk} We will call a function  $u$ as in (ii) of Theorem~\ref{MOTS}  a weak solution of $(**)$ and its level sets  $(\Sigma_t=\{u=t\})_{t\ge 0}$  a weak solution  of $(*)$  (see Definition~\ref{weak}). Theorem~\ref{MOTS} (ii) then states that there exists a weak solution  of $(*)$ with initial condition $\Sigma_0=\partial\Omega$, $(\Sigma_t)_{t\ge 0}$,  that converges to a generalized MOTS that lies outside the outermost MOTS. Note also that the fact that the outermost MOTS has the form $\Sigma_\infty=\partial\Omega_\infty$, where $\Omega_\infty$ is an open set, is not an assumption---this is always the case with $\Omega_\infty$ being the union of all weakly outer trapped sets in $M$, that is open sets with  weakly outer trapped boundary (i.e. satisfying $\theta^+\le 0$), as is shown in \cite{AM09}.
\end{Remark}

\begin{Remark}
 In case $\partial \Omega_\out=\emptyset$, then Theorem~\ref{MOTS} still holds with the functions $\hat{u}_{\varepsilon}$, as in (i), being defined over all of $\Omega$ (see Theorem \ref{kto0} (iii)).
 \end{Remark}
 \begin{Definition}\label{weakMOTS} Let $E\subset M$ be a finite perimeter set. We will say that the reduced boundary of $E$, $\partial^*E$,  is a generalized MOTS if the following hold 
 \begin{itemize}
 \item $\mu_E=\H^n\res\partial^*E$ carries a generalized mean curvature vector $\vec H$  and
 \item For $\H^n$-a.e. point on $\partial^*E$
 \[\vec H+ P\nu=0\,,\,\,\text{where }P=\nu^i\nu^jK_{ij}\]
 and $\nu$ is the measure theoretic outer pointing unit normal to $\partial^*E$.
  \end{itemize}
 (See  \cite[Definition 16.5 and \S14]{LSgmt} for precise definitions of $\partial^*E$, $\vec H$ and $\nu$).
 \end{Definition}
 \begin{Remark}[on Definition~\ref{weakMOTS}] \label{weakrmk}
 If $\partial^* E$ is a generalized MOTS, then by Allard's regularity theorem \cite{Al} (see also \cite{Alex}) we infer that, away from a set of $\H^n$-measure zero, $\partial^*E$ is a $C^{1,\a}$ hypersurface for any $\a\in (0,1)$. This implies that locally (away from a set of $\H^n$-measure zero) it is the graph of a function that satisfies  equation \eqref{Jang} weakly, and using standard PDE methods we obtain that  $\partial^* E$ is smooth, and thus a MOTS in the classical sense, away from a set of $\H^n$-measure zero.

 Furthermore, since the mean curvature is bounded on the reduced boundary, we also have that if  $\partial^* E$ is a generalized MOTS then $\H^n(\partial E\setminus\partial^*E)=0$.
 \end{Remark}
 \begin{Remark}The proof of the main theorem, Theorem~\ref{main}, is given in Theorems \ref{kto0}, \ref{blowup}, \ref{weak existence} and \ref{MOTSconv}. 

In Section \ref{properties}, we give various properties for the graphs of the functions $\hat u_\e$, $\hat u$, the most important being a minimizing property (see Lemmas \ref{emin},  \ref{eminu}). Furthermore, in addition to (locally) uniform convergence of the functions $\hat u_\e$ to $\hat u$, we obtain  convergence, in the sense of varifolds, of their graphs (see Theorem~\ref{mainconvii}).  \end{Remark}




\noindent{\bf Remarks on further directions.} 

 We believe that weak solutions $(\Sigma_t)_{t\ge0}$ (as in Remark~\ref{thmrmk}) actually  converge to the outermost MOTS. However, as our proof yields only {\it weak} convergence of the $\Sigma_t$'s as $t\to \infty$, we can only deduce that the limit is a {\it generalized} MOTS. If the generalized limit can be shown to be regular, then, as it lies outside the outermost MOTS,  the two must coincide. 
 We believe that it should be possible to adapt techniques from \cite{W00} to show that the level sets $\Sigma_t$ have a better minimization property (than the one-sided minimization property of Lemma~\ref{eminu}) and thus obtain better regularity for the limit. At the end of Section \ref{properties} we discuss this  in greater detail.

\begin{proof}
Since $\hat u|_{\partial\Omega}=0$, either $\hat{u}\leq0$ or $\hat{u}$ has an interior maximum. At an interior maximum point we have 
\begin{align*}
\max_{\Omega}\kappa \hat{u}= g^{ij}\hat{u}_{ij}-sg^{ij}K_{ij}+\frac{s}{\varepsilon}\leq (n+1)\lambda+\frac{1}{\varepsilon}.
\end{align*}
Since, for $\varepsilon\leq\frac{1}{(n+1)\lambda}$, zero is a subsolution of $(*_{\hat{\varepsilon},\kappa,s})$  we find
\begin{equation*}
0\leq \hat{u}\leq \frac{(n+1)\lambda}{\kappa}+\frac{1}{\varepsilon\kappa}\le \frac{2}{\varepsilon\kappa}.
\end{equation*}
\end{proof}

\begin{proof} For the gradient function $v(x,f(x)):=\sqrt{1+|\nabla f(x)|^2}$ of a hypersurface  $N=\graph f$ we have
\begin{equation}\label{jacobi}
\Delta^N v=\frac{2}{v}|\nabla^N v|^2-v^2\bar g(\nabla^N H,\tau)+v|A|^2+v\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma),
\end{equation}
where $\tau=\frac{\partial}{\partial z}$ is the unit vector pointing in the upward, $\mathbb{R}$, direction of $M\times\mathbb{R}$, $\nu$ is the upward pointing unit normal to $N=\graph f$, $H$ and $A$ are the mean curvature and the second fundamental form of $N$,  $\gamma:=\frac{\text{pr}_{TM}\nu}{|\text{pr}_{TM}\nu|}$ in case $\nu\ne \tau$ and zero otherwise,  and $\Ric=\Ric_M$ is the Ricci curvature of $M$. For details of the derivation of \eqref{jacobi} see \cite[(13)]{S08}. Recall also that $\bar g$ is the metric in the product manifold $M\times\R$ as defined in \eqref{product}.  We follow the general approach in \cite[Lemma 3.2]{S08} to show that we can obtain a gradient bound given an a-priori height bound and compute $\Delta^N(wv)$, where
 $w(x,z):=\exp(-\eta z)$, for $(x,z)\in M\times\R$ and $\eta>0$ a constant to be chosen later. For the function $w$ we have
\[\nabla^N w=-\eta w\left(\tau-\frac1v\nu\right)\,\text{ and }\,\Delta^N w=\eta^2\left(1-\frac{1}{v^2}\right)w+\eta\frac{H}{v}w,\]
and combining these with \eqref{jacobi}, we obtain
\begin{equation}\label{jacobi2}
\begin{split}
\Delta^N(wv)=\frac{2}{v}\bar g(\nabla v,\nabla (wv))+wv\Biggl(&|A|^2+\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)\\
&+\eta^2\left(1-\frac{1}{v^2}\right)+\eta\frac{H}{v}-v\bar g(\nabla^N H,\tau)\Biggr).
\end{split}
\end{equation}
In order to obtain a contradiction, define $C_1:=\sup_{\partial\Omega}\varepsilon\sqrt{1+|\nabla \hat{u}|^2}$ and assume 
\begin{equation}\label{contradiction1}
\sup_{\Omega}(\exp(-\eta \hat{u})\varepsilon\sqrt{1+|\nabla \hat{u}|^2})>\max\{C_1,1\},
\end{equation}
which must be attained at an interior point $x_0$. Letting $N=\graph\hat{u}$, equation $(*_{\hat{\varepsilon},\kappa, s})$ implies that 
\begin{equation}\label{floweqn}
H+sP=\dfrac{s}{\varepsilon v}-\kappa\hat{u},
\end{equation}
where $H+P$ is the null mean curvature of $N$. 
Now, using the expression for $\nabla^N w$,  we find 
\begin{align*}
wv^2\bar g(\nabla^N H,\tau)=&-\frac{s}{\varepsilon}\bar g(\nabla^N (wv),\tau)+\frac{sv}{\varepsilon}\bar g(\nabla^N w,\tau)-wv^2s\bar g(\nabla^N P,\tau)\\
&-wv^2\kappa \bar g(\nabla^N \hat u,\tau)\\
=&-\frac{s}{\varepsilon}\bar g(\nabla^N (wv),\tau)-\frac{s}{\varepsilon}\eta wv\left(1-\tfrac{1}{v^2}\right)-wv^2s\bar g(\nabla^N P,\tau)\\
&-wv^2\kappa \bar g(\nabla^N  \hat u,\tau).
\end{align*}
Note that $\nabla^NP=\ov\nabla P-\bar g(\ov\nabla P,\nu)\nu$ (where $\ov\nabla=\nabla^{M\times\R}$),  $K$ (as well as $\nu$)  is extended trivially in the $\tau$ direction so that $\bar g(\ov\nabla P,\tau)=0$, and $\bar g(\tau,\nu)=\frac{1}{v}$. Using these, we obtain
\begin{equation}\label{MNest}
\begin{split}
vs\bar g(\nabla^N P,\tau)=-s\bar g(\ov\nabla P,\nu)&\geq-c(1+|A|),\\
v\kappa \bar g(\nabla^N  \hat{u},\tau)=-\kappa \bar g(\ov\nabla \hat{u},\nu)&=\frac{\kappa|\nabla \hat{u}|^2}{v}\geq0,
\end{split}
\end{equation}
where $c=c(n, \|K\|_{C^1})\ge1$, so that, using the Cauchy--Schwarz inequality, we have
\begin{equation}\label{nablaHest}
\begin{split}
wv^2\bar g(\nabla^N H,\tau)\leq-\frac{s}{\varepsilon}\bar g(\nabla^N (wv),\tau)&-\frac{s}{\varepsilon}\eta wv\left(1-\frac{1}{v^2}\right)+2c^2wv+ wv\frac{|A|^2}{2}.
\end{split}
\end{equation}
At a maximum point $x_0$, where $\Delta^N(wv)\leq0$ and $\nabla^N(wv)=0$, (\ref{jacobi2}) becomes
\begin{align*}
0\geq&|A|^2 +\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)+\eta^2\left(1-\frac{1}{v^2}\right)+\eta\frac{H}{v}-v\bar g(\nabla^N H,\tau),
\end{align*}
where the constant $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}. Using (\ref{floweqn}),  \eqref{nablaHest} and Lemma \ref{supest}, we obtain
\[
\begin{split}
0\geq \frac{|A|^2}{2}&+\left(1-\frac{1}{v^2}\right)\left(\Ric(\gamma,\gamma)
+\frac{s\eta}{\varepsilon}+\eta^2\right)\\
&+\frac{s\eta}{\varepsilon v^2}-\eta\frac{\|K\|_{C^0}}{v}-\frac{2\eta}{\e v}-2c^2.
\end{split}
\]
By the assumption (\ref{contradiction1}), we find that $v(x_0)>\frac{1}{\varepsilon}$ and thus $(1-\frac{1}{v^2})>\frac{1}{2}$ when $\varepsilon\leq\frac{1}{2}$. Then, the above becomes
\begin{equation*}
0\geq \frac{\eta^2}{2}+\frac{1}{2}\Ric(\gamma,\gamma)-2c^2-\eta\left(\frac12\|K\|_{C^0}+2\right),
\end{equation*}
where the constant $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}, and setting $\eta=\eta(n,\Ric,\|K\|_{C^1})$ large enough so that the right-hand side is strictly positive leads to a contradiction and thus  hypothesis (\ref{contradiction1}) is false.
\end{proof}

\begin{proof}
Since $\partial\Omega$ is strictly mean convex and outer untrapped with respect to the outward pointing unit normal (so that on $\partial \Omega$ $H+sP>0$ for $s\in[0,1]$) we can use the classical barrier construction of Serrin, as presented in   \cite[Theorem 14.6]{GT01}, to obtain the desired boundary gradient estimate. Since equation $(*_{\hat{\varepsilon},\kappa,s})$ is expressed in terms of the geometry of $\graph\hat{u}$, in order to utilize the outer untrapped condition of the boundary $\partial\Omega$, we re-write it instead in terms of the geometry of the individual level sets of $\hat{u}$. To this end, we multiply $(*_{\hat{\varepsilon},\kappa,s})$ by $v^3=\sqrt{1+|\nabla\hat{u}|^2}^3$ to obtain
\begin{align*}

Q(\hat{u}):=&
(1+|\nabla\hat{u}|^2)\left(g^{ij}-\dfrac{\nabla^i\hat{u}\nabla^j\hat{u}}{|\nabla \hat{u}|^2+1}\right)\nabla_{ij}\hat{u}\\
&-s\sqrt{1+|\nabla\hat{u}|^2}^3\left(g^{ij}-\dfrac{\nabla^i\hat{u}\nabla^j\hat{u}}{|\nabla \hat{u}|^2+1}\right)K_{ij}\\
&+\frac{s}{\varepsilon}(1+|\nabla \hat{u}|^2)-\kappa\hat{u}\sqrt{1+|\nabla \hat{u}|^2}^3,
\end{align*}
and decompose it, as in  \cite[(14.43)]{GT01}, into the following coefficients 
\begin{align}\label{levelset}
Q\hat u&=(\Lambda a^{ij}_{\infty}+a^{ij}_0)\nabla_{ij}\hat{u}+|\nabla\hat{u}|\Lambda b_{\infty}+b_0=0,
\end{align} 
where 
\[a^{ij}_{\infty}(x,z,p)=a^{ij}_{\infty}\left(x,\frac{p}{|p|}\right)=\left(g^{ij}-\frac{p^ip^j}{|p|^2}\right),\,\,a^{ij}_0=\frac{p^ip^j}{|p|^2},\,\,\Lambda=1+|p|^2,\]
\[b_{\infty}(x,z,p)=b_{\infty}\left(x,z,\frac{p}{|p|}\right)=-sK_{ij}\left(g^{ij}-\frac{p^ip^j}{|p|^2}\right)-\kappa z\]
and
\[b_0=-\kappa z\frac{\Lambda}{\Lambda^{1/2}+|p|}-sK_{ij}\left(g^{ij}\frac{\Lambda}{\Lambda^{1/2}+|p|}+\frac{p^ip^j}{|p|}\frac{\Lambda^{1/2}}{\Lambda^{1/2}+|p|}\right)+\frac{s}{\varepsilon}\Lambda.\]
Then
\begin{equation*}a^{ij}_{\infty}\left(x,\frac{\nabla\hat{u}}{|\nabla\hat{u}|}\right)\frac{\nabla_{ij}\hat{u}}{|\nabla\hat{u}|}+b^{ij}_{\infty}\left(x,u,\frac{\nabla\hat{u}}{|\nabla\hat{u}|}\right)=-(H+sP)-\kappa \hat{u}, 
\end{equation*}
where here $H+P$ is the null mean curvature of the {\it level sets} of $\hat u$ with respect to the outward pointing unit normal. We see that $b_{\infty}$ is non-increasing in $z$, and also that the correction terms $a_0$ and $b_0$, that arise when considering the curvature of the level sets instead of the graph, are of the order required by the structure condition (14.50) (see also (14.59)) of  \cite[Theorem 14.6]{GT01}. That is, $a_0^{ij}=o(\Lambda)$ and $b_0=o(|p|\Lambda)$ as $|p|\to\infty$. Furthermore, since $\partial \Omega$ is outer untrapped, we see that the boundary curvature condition (14.51) of  \cite[Theorem 14.6]{GT01} is also satisfied since $H-b_{\infty}=H+sP> 0$ at all points on the boundary $\partial\Omega$.  \cite[Theorem 14.6]{GT01} can then be applied, which implies the existence of an upper barrier at any boundary point, and which  depends on the mean curvature of the boundary, $K$ and the supremum bound of of $\hat{u}$ (given in Lemma~\ref{supest}). This finishes the proof of the lemma.
\end{proof}

\begin{proof} The proof follows that of \cite[Lemma 3]{SY81}.
The idea is to apply the method of continuity to the equation $(*_{\hat{\varepsilon},\kappa,s})$. To this end, fix $\varepsilon\le \min\left\{\frac{1}{(n+1)\lambda},\frac12\right\}$ and $\k>0$,  and define
\begin{align*}
F^s(w):=\dvg\left(\frac{\nabla w}{\sqrt{|\nabla w|^2+1}}\right)&-s\left(g^{ij}-\dfrac{\nabla^iw\nabla^jw}{|\nabla w|^2+1}\right)K_{ij}\\
&+\dfrac{s}{\varepsilon \sqrt{|\nabla w|^2+1}}-\kappa w.
\end{align*}
For any $\a\in (0,1)$,  the map 
\begin{equation*}
F: C^{2,\alpha}_0(\bar{\Omega})\times[0,1]\to C^{\alpha}(\bar{\Omega}) 
\end{equation*}
given by $F(w,s):=F^s(w)$  has the solution $F(0,0)=0$. Let $I$ be the set of $s$ such that $(*_{\varepsilon,\kappa,s})$ has a solution in $C^{2,\alpha}(\bar{\Omega})$ or equivalently the set of $s$ for which there exists $w\in C^{2,\alpha}_0(\bar{\Omega})$ such that $F(w,s)=0$. Then $0\in I$ and we will show that $I$ is an open and closed subset of $[0,1]$, which implies that $I=[0,1]$, thus proving the lemma. To show that $I$ is closed one uses  the a-priori estimates in Lemmas \ref{supest}, \ref{interiorforkappa} and \ref{kappaexists}, standard PDE estimates (which imply `higher' a-priori estimates for a solution; in particular $C^{2,\a}$ for any $\a\in (0,1)$) and the Arzela-Ascoli theorem. To show that $I$ is open, one has to linearize $F^s$ at a solution $f_0$ and apply the inverse function theorem for Banach spaces. For the details of these two claims we refer the reader to \cite[Lemmas 2 and 3]{SY81}   where the arguments on the fact that $I$ is both open and closed are carried out in detail. We remark that the only difference between our case and \cite[Lemma 3]{SY81} is that one has to add the factor $-\frac{\nabla^i f_0}{\e(|\nabla f_0|^2+1)^\frac32}$
in the term $B^i$ that appears in the linearization of $F^s$ at a solution $f_0$ (the notation being here as in \cite[Lemma 3]{SY81}).











\end{proof}

\begin{proof}
As we explained before the statement  of the theorem, using standard results of $(C,1)$-minimal sets (see \cite{MaMi}), we have  that the graphs $N_{\k_ i}$ of the functions $\hat{u}_{\varepsilon,\k_i}$ converge locally smoothly to  a smooth embedded hypersurface $N$ in $\bar{\Omega}\times\mathbb{R}$. Moreover, since $N$ inherits its orientation from $N_{\k_i}$,  it follows that $\frac{1}{v_{\k_i}}=(\sqrt{1+|\nabla\hat{u}_{\varepsilon, \k_i}|^2})^{-1}$ converges (smoothly) to the vertical component, $\frac{1}{v}$, of the unit normal vector of $N$.   In view of \eqref{Harnack}, this limit satisfies $\Delta^N\left(\frac{1}{v}\right)+\frac{1}{\varepsilon}\bar g\left(\nabla^N \frac{1}{v},\tau\right)-\frac{\beta}{v}\leq0$. The Hopf maximum principle then says that on each connected component of $N$, we have that $\frac{1}{v}$ either vanishes identically---and the connected component is cylindrical---or else is everywhere positive---and the connected component is a graph. Note that here no component can be a cylinder, since the functions $\hat{u}_{\varepsilon,\k_i}$ are non-negative. Furthermore, the boundary gradient estimates given in Lemma~\ref{boundaryforkappa} ensures that the graphs $N_{\k_i}$ must remain bounded near $\partial\Omega$, and thus  the limit $N$ is a graph near $\partial\Omega$.
Therefore, $N$ is the graph of a function, which we call $\hat{u}_{\varepsilon}$, defined on an open (non-empty) subset of $\Omega$, which we call $\Omega_\e$. The locally smooth convergence $\hat u_{\e, \k_i}\to\hat u_\e$ then immediately yields that $\hat{u}_{\varepsilon}$ satisfies $(*_{\hat\varepsilon})$ in ${\Omega}_\e$ and diverges to infinity on approach to $\partial\Omega_\e\setminus\partial\Omega$.  This finishes the proof of (i).

To prove (ii), we need to show that the set $\Sigma_\e=\partial\Omega_\e\setminus \partial \Omega$, where the function $\hat u_\e$ tends to infinity, is a MOTS (note $\Sigma_\e$ as defined here might have more than one connected component). Since $N=\graph \hat u_\e$ over $\Omega_\e$ and $\hat u_\e$ satisfies $(*_{\hat\varepsilon})$, we have that
$H+P=\frac{1}{\e\sqrt{1+|\nabla u_{\hat\e}|^2}}=\frac 1\e \nu^{n+2}$, where $H=H(x)$ is the mean curvature of $N$ at $(x, \hat u_\e(x))$, $P=P(\nu)=(g^{ij}-\nu^i\nu^j)K_{ij}$, $\nu=\nu(x)$ is the upward pointing unit normal to $N$ at $(x, \hat u_\e(x))$ and $\nu^{n+2}$ is its vertical component. We consider vertical translations, $N_{\a_i}= N-\a_i$, of $N$ for a sequence $\{\a_i\}_{i\in\N}\subset \R$ with $a_i\uparrow \infty$. $N_{\a_i}$ have uniformly bounded mean curvature and thus are  $(C,1)$-minimal sets. Therefore, we can argue as with the convergence $N_{\k_ i}\to N$, using the results of \cite{DS93, MaMi}, to conclude that, after passing to a subsequence, $N_{\a_i}\to \wt N$ locally smoothly (note again that the mean curvature of $N_{\a_i}$ can be expressed in terms of its normal). Since we also have that $N_{\a_i}\to \Sigma_\e\times \R$ locally uniformly, we conclude that $\wt N =\Sigma_\e\times \R$. The locally smooth convergence $N_{\a_i}\to \Sigma_\e\times \R$, along with the fact that for $N=\graph \hat u_\e$ we have
$H+P=\frac 1\e \nu^{n+2}$, implies that the limit  $\Sigma_\e\times \R$ is a MOTS.

Finally, we note that if $\Omega$ does not contain a closed MOTS in its interior, then $\Sigma_\e=\emptyset$ and therefore (iii) holds.
\end{proof}


\begin{Remark} It is interesting to observe that the elliptic regularization problem $(*_{\hat{\varepsilon}})$ provides a new way to locate MOTS in space-time initial data sets with a mean convex, outer-untrapped hypersurface. In the following section we will show that the hypersufaces $\Sigma_\e$ are not only  MOTS but they are indeed  the outermost MOTS and thus this is actually a way to  locate the outermost MOTS.
\end{Remark}

\begin{proof} We take a similar approach to that of the proof of Lemma~\ref{interiorforkappa}. Let $N=\graph \hat u_\e$ and $v=\sqrt{1+|\nabla \hat u_\e|^2}$, where recall that $\hat u_\e=\e u_\e$ is a solution of $(*_{\hat{\varepsilon}})$. Let also $w(x,z):=\exp(-\varepsilon\eta z)$ for $(x,z)\in M\times\R$ and $w_0=\exp(-\eta T)$, so that $w-w_0=0$ when $z=\e^{-1}T$. We compute $\Delta^N((w-w_0)v)$ on $N$, similarly to \eqref{jacobi2} in the proof of Lemma  \ref{interiorforkappa}, as follows. We first note that
\[
\nabla^N w=-\e\eta w\left(\tau-\frac1v\nu\right)\,,\,\,\,\Delta^N w=\e^2\eta^2\left(1-\frac{1}{v^2}\right)w+\e\eta\frac{H}{v}w,
\]
where the notation here and throughout this proof is as in the proof of Lemma  \ref{interiorforkappa}. Thus (using \eqref{jacobi} from the proof of Lemma  \ref{interiorforkappa}) we obtain
\begin{equation}\label{newJacobiEqn}
\begin{split}
\Delta^N((w-w_0)v)=&\frac{2}{v}\bar g(\nabla^Nv,\nabla^N((w-w_0)v))
\\
&+(w-w_0)v\Bigg(|A|^2+\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)\\
&+(\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}-v\bar g(\nabla^NH,\tau)\Bigg)\\
&+w_0v\left((\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}\right).
\end{split}
\end{equation}
To argue by contradiction, define $C_1:=\sup_{\partial\Omega}\varepsilon\sqrt{1+|\nabla \hat{u}_\e|^2}$ and assume 
\begin{equation}\label{contradiction}
\sup_{\Omega_T}((\exp(-\eta \varepsilon\hat{u})-\exp(-\eta T))\varepsilon\sqrt{1+|\nabla \hat{u}_\e|^2})>\max\{C_1,1\},
\end{equation}
which must be attained at an interior point $x_0$. Since $N=\graph\hat{u}_\e$, equation $(*_{\hat{\varepsilon}})$ implies that 
\begin{equation}\label{floweqn2}
H+P=\dfrac{1}{\varepsilon v},
\end{equation}
where $H+P$ is the null mean curvature of $N$.
Proceeding as in Lemma~\ref{interiorforkappa}, analogous to (\ref{nablaHest}) (using also \eqref{MNest} and the expression for $|\nabla^Nw|$), we obtain the following estimate
\begin{align*}
(w-w_0)v^2\bar g(\nabla^NH,\tau)=&-\frac{1}{\varepsilon}\bar g(\nabla^N((w-w_0)v),\tau)\\
&-{\eta} wv\left(1-\frac{1}{v^2}\right)-(w-w_0)v^2g(\nabla^NP,\tau)\\
\leq&-\frac{1}{\varepsilon}\bar g(\nabla^N((w-w_0)v),\tau)\\
&-(w-w_0)v\left({\eta}\left(1-\frac{1}{v^2}\right)-2c^2-\frac{|A|^2}{2}\right)\\
&-w_0v{\eta}\left(1-\frac{1}{v^2}\right),
\end{align*}
where $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}.
At a maximum point $x_0$, where $\Delta((w-w_0)v)\leq0$ and $\nabla((w-w_0)v)=0$, \eqref{newJacobiEqn} reduces to
\begin{align*}
0\geq (w-w_0)v\Bigg(&|A|^2+\left(1-\frac{1}{v^2}\right)\Ric(\gamma,\gamma)\\
&+(\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}-v\bar g(\nabla^NH,\tau)\Bigg)\\
&+w_0v\left((\varepsilon\eta)^2\left(1-\frac{1}{v^2}\right)+\varepsilon\eta\frac{H}{v}\right).
\end{align*}
After implementing the above estimates and also using \eqref{floweqn2}, this becomes
\begin{align*}
0\geq(w-w_0)v\Bigg(\frac{|A|^2}{2}&+\left(1-\frac{1}{v^2}\right)\Bigl(\Ric(\gamma,\gamma)+\eta+(\varepsilon\eta)^2\Bigr)\\
&\hspace{3cm}+\frac{\eta}{v^2}-\varepsilon\eta\frac{\|K\|_{C^0}}{v}-2c^2\Bigg)\\
&+w_0v\left((\eta+(\varepsilon\eta)^2)\left(1-\frac{1}{v^2}\right)+\frac{\eta}{v^2}-\varepsilon\eta\frac{\|K\|_{C^0}}{v}\right).
\end{align*}
By the contradiction hypothesis (\ref{contradiction}), we find that $v(x_0)>\frac{1}{\varepsilon}$ and thus $(1-\frac{1}{v^2})>\frac{1}{2}$, provided that $\varepsilon\leq\frac{1}{2}$. Therefore, after discarding some  positive terms from the right-hand side, we obtain
\begin{equation*}
\begin{split}
0&\geq (w-w_0)v\Bigg(\left(1-\frac{1}{v^2}\right)\left({\eta}+\Ric(\gamma,\gamma)-4c^2\right)+\varepsilon^2\eta\left(\frac{\eta}{2}-\|K\|_{C^0}\right)\Bigg)\\
&\quad+w_0\varepsilon^2\eta\left(\frac{\eta}{2}-\|K\|_{C^0}\right),
\end{split}
\end{equation*}
where the constant $c=c(n, \|K\|_{C^1})$ is the constant from \eqref{MNest}. For $\eta=\eta(n,\Ric,\|K\|_{C^1})$ large enough the right-hand side of the above expression becomes  strictly positive, leading to a contradiction. In other words, \eqref{contradiction} cannot be true and therefore we have
\[\sup_{\Omega_T}((\exp(-\eta \varepsilon\hat{u}_\e)-\exp(-\eta T))\varepsilon\sqrt{1+|\nabla \hat{u}_\e|^2})\le\max\{C_1,1\}.\]
For $u_\e=\e\hat u_\e$ we then have
\[\begin{split}\sup_{\Omega_T}((\exp(-\eta{u}_\e)-\exp(-\eta T))\sqrt{\e^2+|\nabla {u}_\e|^2})&\le\max\{C_1,1\}\\
&\le \sup_{\partial\Omega}(1+\sqrt{\e^2+|\nabla {u}_\e|^2}).
\end{split}\]
Restricting now to the region $\Omega_{T/2}$, where 
\[\exp(-\eta{u}_\e)-\exp(-\eta T)\ge \exp(-\eta T/2)-\exp(-\eta T)\ge \frac{\eta T}{2}\exp(-\eta T),\]
we obtain  the required estimate.
\end{proof}

