\begin{proof}[Proof of Lemma \ref{normalintest}]
This follows as in \cite[Lemma 2.1]{MS}, keeping track of the extra ``$P$-term''. 
Let $\psi$ be a smooth function such that $0\leq\psi\leq1$, $\psi=1$ on $\Omega_{\delta}:=\{x\in\Omega_0|\text{dist}(x,\partial\Omega_0)>\delta\}$, $\psi=0$ on $\partial\Omega$ and $|D\psi|\leq\gamma/\delta$ for some $\gamma>1,\,\delta>0$. Multiplying $(*_{\varepsilon})$ by $\psi$ and integrating by parts we find
\begin{equation*}\begin{split}
\int_{\Omega_\d}\frac{1 }{\sqrt{\varepsilon^2+|\nabla u_{\varepsilon}|^2}}dx\leq \int_{\Omega_0\setminus\Omega_{\delta}}\frac{\nabla \psi\cdot \nabla u_{\varepsilon}}{\sqrt{\varepsilon^2+|\nabla u_{\varepsilon}|^2}}dx+\int_{\Omega_0}P(u_\e)\psi dx,
\end{split}\end{equation*}
where $P(u_\e)=\left(g^{ij}-\frac{\nabla^i u_\e\nabla^j u_\e}{|\nabla u_\e|^2+\e^2}\right) K_{ij}$.
Since $|P(u_\e)|\le (n+2)\l$, we have
\[\int_{\Omega_\d}\frac{1 }{\sqrt{\varepsilon^2+|\nabla u_{\varepsilon}|^2}}dx\leq\frac{\gamma}{\delta}|\Omega_0\setminus\Omega_{\delta}|+(n+2)\lambda|\Omega|\]
and after letting $\d\to 0$ and then $\gamma\to 1$ we obtain the result.
\end{proof}


